"""Fill text to a column width, keeping paragraphs apart."""
import re

_PARAGRAPH_BREAK = re.compile(r"\n\s*\n")


def wrap(text, width):
    """Greedy word fill to width. Blank lines separate paragraphs, which are joined by one empty line. Words are never split."""
    if isinstance(width, bool) or not isinstance(width, int):
        raise ValueError(f"width must be an int: {width!r}")
    if width < 1:
        raise ValueError(f"width must be >= 1: {width}")
    paragraphs = [p.split() for p in _PARAGRAPH_BREAK.split(text)]
    blocks = []
    for words in paragraphs:
        if not words:
            continue
        lines = []
        line = words[0]
        for word in words[1:]:
            if len(line) + 1 + len(word) <= width:
                line += " " + word
            else:
                lines.append(line)
                line = word
        lines.append(line)
        blocks.append("\n".join(lines))
    return "\n\n".join(blocks)

