import contextlib
import io
import unittest

from textkit.cli import main
from textkit.wrap import wrap


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class WrapTest(unittest.TestCase):
    def test_example(self):
        self.assertEqual(wrap("aaa bbb ccc", 7), "aaa bbb\nccc")

    def test_greedy_fill(self):
        self.assertEqual(wrap("one two three four five", 9), "one two\nthree four\nfive")

    def test_line_exactly_width_is_kept(self):
        self.assertEqual(wrap("ab cd", 5), "ab cd")
        self.assertEqual(wrap("ab cd", 4), "ab\ncd")

    def test_whitespace_inside_paragraph_collapses(self):
        self.assertEqual(wrap("a\n  b\t\tc\n\nd", 10), "a b c\n\nd")

    def test_paragraphs_are_separated_by_one_empty_line(self):
        self.assertEqual(wrap("one\n\n\n   \ntwo", 20), "one\n\ntwo")

    def test_blank_lines_with_whitespace_separate_paragraphs(self):
        self.assertEqual(wrap("one\n \t \ntwo", 20), "one two")
        self.assertEqual(wrap("one\n\t\ntwo", 20), "one\n\ntwo")

    def test_no_leading_or_trailing_blank_lines(self):
        self.assertEqual(wrap("\n\n  hi there \n\n", 20), "hi there")

    def test_empty_or_blank_text(self):
        self.assertEqual(wrap("", 10), "")
        self.assertEqual(wrap(" \n \n\t", 10), "")

    def test_long_word_goes_on_its_own_line_unbroken(self):
        self.assertEqual(wrap("a abcdefghijkl b", 5), "a\nabcdefghijkl\nb")

    def test_long_word_at_start_and_end(self):
        self.assertEqual(wrap("abcdefghij x", 4), "abcdefghij\nx")
        self.assertEqual(wrap("x abcdefghij", 4), "x\nabcdefghij")

    def test_hyphenated_words_are_not_split(self):
        self.assertEqual(wrap("state-of-the-art tool", 10), "state-of-the-art\ntool")
        self.assertEqual(wrap("a well-known fact", 8), "a\nwell-known\nfact")

    def test_width_one_puts_each_word_on_its_own_line(self):
        self.assertEqual(wrap("a bb c", 1), "a\nbb\nc")

    def test_width_below_one_raises(self):
        for width in [0, -1]:
            with self.subTest(width=width):
                with self.assertRaises(ValueError):
                    wrap("hello", width)

    def test_non_int_width_raises(self):
        for width in [2.5, "5", None, True]:
            with self.subTest(width=width):
                with self.assertRaises(ValueError):
                    wrap("hello", width)


class WrapCommandTest(unittest.TestCase):
    def test_prints_wrapped_text(self):
        self.assertEqual(run("wrap", "aaa bbb ccc", "--width", "7"), (0, "aaa bbb\nccc\n", ""))

    def test_default_width_is_40(self):
        text = "word " * 9 + "end"
        code, out, _ = run("wrap", text)
        self.assertEqual(code, 0)
        self.assertEqual(out, wrap(text, 40) + "\n")
        self.assertEqual(out.splitlines()[0], "word word word word word word word word")

    def test_width_zero_exits_2(self):
        code, out, err = run("wrap", "x", "--width", "0")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

    def test_commands_lists_wrap(self):
        code, out, _ = run("commands")
        self.assertEqual(code, 0)
        self.assertIn("wrap", out.split())


if __name__ == "__main__":
    unittest.main()

